package main

import (
	"context"
	"database/sql"
	"encoding/json"
	"fmt"
	"os"

	_ "github.com/go-sql-driver/mysql"

	"case_runner/db"
)

const seed = `INSERT INTO sales (id, region, city, sold_on, amount) VALUES (1, 'north', 'leeds', '2024-01-05', 10.50), (2, 'north', 'york', '2024-01-20', 4.25), (3, 'south', 'bath', '2024-02-02', 7.00)`

type results map[string]any

func (r results) record(name string, read func() (any, error)) {
	value, err := read()
	if err != nil {
		r[name] = "error: " + err.Error()
		return
	}
	r[name] = value
}

func main() {
	conn, err := sql.Open("mysql", os.Getenv("DATABASE_URL"))
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	defer conn.Close()
	conn.SetMaxOpenConns(1)

	ctx := context.Background()
	for _, statement := range []string{seed} {
		if _, err := conn.ExecContext(ctx, statement); err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
	}

	queries := db.New(conn)
	output := results{}
	output.record("revenue_rollup", func() (any, error) { return queries.RevenueRollup(ctx) })
	output.record("monthly_rollup", func() (any, error) { return queries.MonthlyRollup(ctx) })
	output.record("positional_rollup", func() (any, error) { return queries.PositionalRollup(ctx) })

	encoder := json.NewEncoder(os.Stdout)
	encoder.SetIndent("", "  ")
	if err := encoder.Encode(output); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
}
